#!/usr/bin/env python3
"""Templates for the scaffold generator. Token replacement (__TOKEN__) avoids
brace-escaping so template bodies are real, runnable code.

Every template bakes in a hard-won gotcha-fix so generated artifacts start
correct instead of re-learning the same lessons.
"""
from __future__ import annotations

import os

DAEMON_PY = '''#!/usr/bin/env python3
"""__NAME__ — daemon (generated by the arcturion-engineering scaffold skill).

Gotchas baked in (hard-won lessons):
  * runtime != source: installed as a LaunchAgent it runs from the install copy,
    not this repo path — edit source, then re-deploy (bootout -> bootstrap).
  * load gate: heavy work is skipped when an optional external check says the
    machine is overloaded (set __UPPER___LOAD_CHECK to an executable that exits 2
    to mean "too hot / too busy"; unset = always run).
  * idempotent: a pid lock prevents a second instance.
  * /health endpoint for universe health checks.
"""
from __future__ import annotations
import json, os, signal, subprocess, sys, threading, time
from http.server import BaseHTTPRequestHandler, HTTPServer

NAME = "__NAME__"
PORT = int(os.environ.get("__UPPER___PORT", "__PORT__"))
LOAD_CHECK = os.environ.get("__UPPER___LOAD_CHECK", "")
STATE_DIR = os.environ.get("__UPPER___STATE_DIR") or os.path.join(
    os.environ.get("XDG_STATE_HOME") or os.path.expanduser("~/.local/state"), NAME)
LOCK = os.path.join(STATE_DIR, f"{NAME}.pid")
_state = {"started": time.time(), "ticks": 0, "healthy": True}


def load_ok() -> bool:
    """Load gate. True unless the optional LOAD_CHECK command exits 2.
    No checker configured, or checker missing/failing -> assume ok."""
    if not LOAD_CHECK:
        return True
    try:
        return subprocess.run([LOAD_CHECK], capture_output=True, timeout=15).returncode != 2
    except Exception:
        return True


def _lock_pid_is_ours(pid: int) -> bool:
    # PID liveness alone is unsafe: after a reboot the OS reuses PIDs, so a stale
    # lock can point at an unrelated process and every respawn would exit
    # "already running". The lock counts only if the live PID is actually
    # running this script.
    if pid == os.getpid():
        return True
    try:
        os.kill(pid, 0)
    except (ProcessLookupError, PermissionError):
        return False
    try:
        out = subprocess.run(["ps", "-p", str(pid), "-o", "command="],
                             capture_output=True, text=True, timeout=5).stdout
    except Exception:
        return False
    return os.path.basename(__file__) in out


def acquire_lock() -> bool:
    os.makedirs(STATE_DIR, exist_ok=True)
    if os.path.exists(LOCK):
        try:
            pid = int(open(LOCK).read().strip())
        except ValueError:
            pid = -1
        if pid > 0 and _lock_pid_is_ours(pid):
            return False  # already running
        try:
            os.remove(LOCK)  # stale: dead, reused-by-another-process, or garbage
        except OSError:
            pass
    with open(LOCK, "w") as fh:
        fh.write(str(os.getpid()))
    return True


def release_lock():
    try:
        os.remove(LOCK)
    except OSError:
        pass


class Health(BaseHTTPRequestHandler):
    def do_GET(self):
        if self.path.rstrip("/") in ("/health", ""):
            body = json.dumps({"name": NAME, "ok": _state["healthy"],
                               "uptime_s": round(time.time() - _state["started"], 1),
                               "ticks": _state["ticks"]}).encode()
            self.send_response(200)
            self.send_header("Content-Type", "application/json")
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)
        else:
            self.send_response(404)
            self.end_headers()

    def log_message(self, *a):
        pass


def serve_health():
    HTTPServer(("127.0.0.1", PORT), Health).serve_forever()


def work_tick():
    """Replace with real work. Skipped when the load gate says no."""
    if not load_ok():
        return
    _state["ticks"] += 1


def main() -> int:
    if not acquire_lock():
        print(f"{NAME} already running", file=sys.stderr)
        return 0
    signal.signal(signal.SIGTERM, lambda *_: (release_lock(), sys.exit(0)))
    threading.Thread(target=serve_health, daemon=True).start()
    try:
        while True:
            work_tick()
            time.sleep(int(os.environ.get("__UPPER___INTERVAL", "60")))
    finally:
        release_lock()
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
'''

