DAEMON_TEST = '''#!/usr/bin/env python3
import os, sys, tempfile, unittest
os.environ["__UPPER___STATE_DIR"] = tempfile.mkdtemp(prefix="__NAME___state_")  # keep the test hermetic
sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
import __NAME__ as d


class T(unittest.TestCase):
    def test_load_ok_returns_bool(self):
        self.assertIn(d.load_ok(), (True, False))

    def test_lock_cycle_is_idempotent(self):
        self.assertTrue(d.acquire_lock())
        self.assertFalse(d.acquire_lock())  # second instance blocked
        d.release_lock()
        self.assertTrue(d.acquire_lock())
        d.release_lock()

    def test_health_state_shape(self):
        self.assertIn("healthy", d._state)


if __name__ == "__main__":
    unittest.main(verbosity=2)
'''

