MCP_PY = '''#!/usr/bin/env python3
"""__NAME__ MCP server stub (stdio JSON-RPC 2.0, zero deps). Generated by the arcturion-engineering scaffold skill."""
from __future__ import annotations
import json, sys

TOOLS = [{"name": "ping", "description": "Echo a message.",
          "inputSchema": {"type": "object",
                          "properties": {"msg": {"type": "string"}},
                          "required": ["msg"]}}]


def handle(req: dict):
    mid, method = req.get("id"), req.get("method")
    if method == "initialize":
        return {"jsonrpc": "2.0", "id": mid, "result": {
            "protocolVersion": "2024-11-05", "capabilities": {"tools": {}},
            "serverInfo": {"name": "__NAME__", "version": "0.1.0"}}}
    if method == "tools/list":
        return {"jsonrpc": "2.0", "id": mid, "result": {"tools": TOOLS}}
    if method == "tools/call":
        p = req.get("params", {})
        if p.get("name") == "ping":
            text = f"pong: {p.get('arguments', {}).get('msg', '')}"
            return {"jsonrpc": "2.0", "id": mid,
                    "result": {"content": [{"type": "text", "text": text}]}}
        return {"jsonrpc": "2.0", "id": mid,
                "error": {"code": -32601, "message": f"unknown tool {p.get('name')}"}}
    if method and method.startswith("notifications/"):
        return None
    return {"jsonrpc": "2.0", "id": mid,
            "error": {"code": -32601, "message": f"unknown method {method}"}}


def main() -> int:
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        try:
            req = json.loads(line)
        except ValueError:
            continue
        resp = handle(req)
        if resp is not None:
            sys.stdout.write(json.dumps(resp) + "\\n")
            sys.stdout.flush()
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
'''

MCP_TEST = '''#!/usr/bin/env python3
import os, sys, unittest
sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
import __NAME__ as m


class T(unittest.TestCase):
    def test_initialize(self):
        r = m.handle({"jsonrpc": "2.0", "id": 1, "method": "initialize"})
        self.assertEqual(r["result"]["serverInfo"]["name"], "__NAME__")

    def test_tools_list(self):
        r = m.handle({"jsonrpc": "2.0", "id": 2, "method": "tools/list"})
        self.assertTrue(any(t["name"] == "ping" for t in r["result"]["tools"]))

    def test_ping_call(self):
        r = m.handle({"jsonrpc": "2.0", "id": 3, "method": "tools/call",
                      "params": {"name": "ping", "arguments": {"msg": "hi"}}})
        self.assertIn("pong: hi", r["result"]["content"][0]["text"])

    def test_unknown_method_errors(self):
        self.assertIn("error", m.handle({"jsonrpc": "2.0", "id": 4, "method": "bogus"}))


if __name__ == "__main__":
    unittest.main(verbosity=2)
'''

CLI_PY = '''#!/usr/bin/env python3
"""__NAME__ — CLI tool (generated by the arcturion-engineering scaffold skill).

Secrets come ONLY from environment variables (never hardcoded, never passed as
CLI arguments where they'd land in shell history or `ps`). Set the variable
named by SECRET_ENV before running, e.g.:  export __UPPER___API_TOKEN=...
"""
from __future__ import annotations
import argparse, os, sys

SECRET_ENV = "__UPPER___API_TOKEN"


def get_secret(env_var: str = SECRET_ENV) -> str:
    """Read a secret from the environment; fail loudly (without echoing it) if absent."""
    value = os.environ.get(env_var, "")
    if not value:
        raise RuntimeError(f"{env_var} is not set")
    return value


def run(args) -> int:
    if args.check_secret:
        try:
            get_secret()
        except RuntimeError as e:
            print(f"__NAME__: {e}", file=sys.stderr)
            return 1
        print(f"__NAME__: {SECRET_ENV} is set")  # never print the value
    else:
        print(f"__NAME__: ok (value={args.value})")
    return 0


def build_parser():
    ap = argparse.ArgumentParser(prog="__NAME__")
    ap.add_argument("--value", default=None)
    ap.add_argument("--check-secret", action="store_true",
                    help=f"verify that {SECRET_ENV} is set (does not print it)")
    return ap


def main() -> int:
    return run(build_parser().parse_args())


if __name__ == "__main__":
    raise SystemExit(main())
'''

CLI_TEST = '''#!/usr/bin/env python3
import os, sys, unittest
from unittest import mock
sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
import __NAME__ as c


class T(unittest.TestCase):
    def test_runs_without_secret(self):
        self.assertEqual(c.run(c.build_parser().parse_args(["--value", "x"])), 0)

    def test_secret_present(self):
        with mock.patch.dict(os.environ, {c.SECRET_ENV: "S3CRET"}):
            self.assertEqual(c.run(c.build_parser().parse_args(["--check-secret"])), 0)

    def test_secret_missing_fails_cleanly(self):
        env = {k: v for k, v in os.environ.items() if k != c.SECRET_ENV}
        with mock.patch.dict(os.environ, env, clear=True):
            self.assertEqual(c.run(c.build_parser().parse_args(["--check-secret"])), 1)


if __name__ == "__main__":
    unittest.main(verbosity=2)
'''

