def _sub(tmpl: str, name: str, port: int = 8790, install_path: str = "", log_dir: str = "") -> str:
    return (
        tmpl.replace("__NAME__", name)
        .replace("__UPPER__", name.upper())
        .replace("__PORT__", str(port))
        .replace("__INSTALL_PATH__", install_path or "<INSTALL_DIR>")
        .replace("__LOG_DIR__", log_dir or os.path.expanduser(f"~/Library/Logs/{name}"))
    )


def render(kind: str, name: str, base: str, port: int):
    """Return [(path, content, executable_bool), ...] for the given kind."""
    if kind == "daemon":
        return [
            (os.path.join(base, f"{name}.py"), _sub(DAEMON_PY, name, port, install_path=base), True),
            (os.path.join(base, f"com.example.{name}.plist"), _sub(DAEMON_PLIST, name, port, install_path=base), False),
            (os.path.join(base, "README.md"), _sub(DAEMON_README, name, port), False),
            (os.path.join(base, "tests", f"test_{name}.py"), _sub(DAEMON_TEST, name), True),
        ]
    if kind == "mcp":
        return [
            (os.path.join(base, f"{name}.py"), _sub(MCP_PY, name), True),
            (os.path.join(base, "tests", f"test_{name}.py"), _sub(MCP_TEST, name), True),
        ]
    if kind == "cli":
        return [
            (os.path.join(base, f"{name}.py"), _sub(CLI_PY, name), True),
            (os.path.join(base, "tests", f"test_{name}.py"), _sub(CLI_TEST, name), True),
        ]
    if kind == "skill":
        return [
            (os.path.join(base, "SKILL.md"), _sub(SKILL_MD, name), False),
            (os.path.join(base, "scripts", "main.py"), _sub(SKILL_MAIN, name), True),
            (os.path.join(base, "tests", "test_main.py"), _sub(SKILL_TEST, name), True),
        ]
    raise ValueError(f"unknown kind: {kind}")
